// IN-DEPTH INSTRUCTIONS FOR C CONSOLE GAME:
// 1. SETUP: Simple printf terminal canvas initialization.
// 2. STATE: Position integers.
// 3. INPUT: Simulation ticks.
// 4. LOOP: Simple for-loop sequence.
#include <stdio.h>
#include <unistd.h>
int main(void) {
    printf("--- C ARCADE GAME ---\n");
    int pos = 0;
    for (int t = 0; t < 5; t++) {
        for (int i = 0; i < 10; i++) {
            if (i == pos) printf("*");
            else printf("-");
        }
        printf("\n");
        pos = (pos + 1) % 10;
        usleep(150000);
    }
    return 0;
}

