struct list_head { struct list_head *next, *prev; };
static inline void list_add(struct list_head *new_node, struct list_head *head) {
    struct list_head *n = head->next; new_node->next = n; new_node->prev = head; head->next = new_node; n->prev = new_node;
}

// Linux Kernel: C lockless kfifo
struct LinuxKfifo { void** buffer; unsigned int size; unsigned int in; unsigned int out; };
static inline int kfifo_put(struct LinuxKfifo* k, void* val) {
    k->buffer[k->in & (k->size - 1)] = val; k->in++; return 1;
}
static inline void* kfifo_get(struct LinuxKfifo* k) {
    void* val = k->buffer[k->out & (k->size - 1)]; k->out++; return val;
}

